def _load_text(filename: str, fallback: str) -> str:
    """Load a build-time generated file. Falls back to fallback if missing."""
    try:
        return (CONTRACT_DIR / filename).read_text(encoding="utf-8").strip()
    except FileNotFoundError:
        return fallback


def _load_json(filename: str, fallback: dict) -> dict:
    """Load a build-time generated JSON file. Falls back to fallback if missing."""
    import json

    try:
        return json.loads((CONTRACT_DIR / filename).read_text(encoding="utf-8"))
    except (FileNotFoundError, json.JSONDecodeError):
        return fallback


