def normalize_model_error(exc: Exception) -> str:
    message = str(exc)
    lowered = message.lower()
    if (
        "insufficient balance" in lowered
        or "402" in lowered
        or "quota" in lowered
        or "billing" in lowered
        or "credit" in lowered
    ):
        return HOSTED_KEY_BALANCE_ERROR
    return message


